ap = argparse.ArgumentParser()
ap.add_argument('--home', required=True)
home = ap.parse_args().home
table, hashes = json.loads(zlib.decompress(base64.b85decode(DATA)))
cached = set(hashes)
new = []
for root in ROOTS:
    for dp, dn, fn in os.walk(os.path.join(home, root)):
        dn.sort()
        for name in sorted(fn):
            path = os.path.join(dp, name)
            if not os.path.isfile(path) or os.path.getsize(path) > 1 << 20:
                continue
            for raw in open(path, 'rb').read().splitlines():
                if hashlib.sha256(raw).hexdigest() not in cached:
                    line = raw.decode(errors='replace').split('#', 1)[0].strip()
                    if line:
                        new.append(line)
variables = {}
for line in new:
    lhs, sep, rhs = line.partition('=')
    if sep and lhs.strip().startswith('$'):
        variables[lhs.strip()[1:]] = rhs.strip()
modbits = {'SHIFT': 1, 'CTRL': 4, 'ALT': 8, 'SUPER': 64}
for line in new:
    lhs, sep, rhs = line.partition('=')
    lhs = lhs.strip()
    if not sep or not (lhs == 'unbind' or lhs.startswith('bind')):
        continue
    flags = lhs[4:] if lhs != 'unbind' else ''
    parts = [p.strip() for p in rhs.split(',', 4 if 'd' in flags else 3)]
    if len(parts) < 2:
        continue
    mask = sum(modbits.get(m, 0) for m in parts[0].upper().split())
    key = parts[1]
    code = int(key[5:]) if key.startswith('code:') else 0
    if key.startswith('code:'):
        key = ''
    if lhs == 'unbind':
        table = [e for e in table if not (e['modmask'] == mask and e['key'] == key
                 and e['keycode'] == code and not e['catch_all'])]
        continue
    if len(parts) != (5 if 'd' in flags else 4):
        continue
    desc = parts[2] if 'd' in flags else ''
    dispatcher, arg = parts[-2:]
    arg = re.sub(r'\$([A-Za-z_]\w*)', lambda m: variables.get(m[1], m[0]), arg)
    table.append({'locked': 'l' in flags, 'mouse': False, 'release': 'r' in flags,
        'repeat': 'e' in flags, 'longPress': False, 'non_consuming': False,
        'auto_consuming': False, 'has_description': 'd' in flags, 'modmask': mask,
        'submap': '', 'submap_universal': 'false', 'key': key, 'keycode': code,
        'catch_all': False, 'description': desc, 'allow_input_capture': False,
        'dispatcher': dispatcher, 'arg': arg})
print(json.dumps(table, separators=(',', ':')))
